  "eod_readinessBody": "The checklist shows what must be done before the day can be closed: every till closed, no transfers waiting, the vault counted. Count the vault every day; a difference is booked straight away as a vault variance.",
  "tm_alertsTitle": "Alerts",
  "tm_alertsBody": "Alerts are raised by your monitoring rules. Open one to see the transactions behind it. Close it with a note when it is explained, or escalate it into a suspicious transaction report. Alerts about the same customer and rule are kept together while they are open.",
  "tm_rulesTitle": "Monitoring rules",
  "tm_rulesBody": "Monitoring rules watch your customers' transactions as they happen. Start from the examples: set a threshold that fits your customers and switch the rule on. Another user authorises the change.",
  "tm_ctrTitle": "Currency transaction reports",
  "tm_ctrBody": "Every customer whose cash in or cash out in a day reaches this threshold is reported. The reports are prepared every night.",
  "rr_introTitle": "Regulatory reports",
  "rr_introBody": "A suspicious transaction report tells the regulator why you suspect a customer's activity. Write the grounds clearly; another officer approves it before it is filed, then record the filing reference here. Currency transaction reports are prepared every night: download them, file them, then record the reference.",
  "tr_movementsTitle": "Cash movements",
  "tr_movementsBody": "Cash movements move bulk cash between a branch vault and the central bank or another bank, or between two branches. Treasury requests and another user approves; the sending custodian dispatches the cash, and it shows as Cash in transit until the receiving custodian counts it in. Any difference in the count is booked as a variance.",
  "tr_positionsTitle": "Settlement positions",
  "tr_positionsBody": "Your position with each settlement bank: what you hold, what you owe through it, and how much room is left above the required minimum.",
  "fs_balanceTitle": "Balance sheet",
  "fs_balanceBody": "The balance sheet shows what the institution owns and owes on a date. Pick a branch to see that branch's own books.",
  "fs_plTitle": "Profit and loss",
  "fs_plBody": "Profit and loss for any period: income less expenses, by line.",
  "fs_cashflowTitle": "Cash flow",
  "fs_cashflowBody": "The cash flow statement explains how your cash changed: profit, then what changed in the rest of the balance sheet.",
  "teller_openTitle": "Open your till",
  "teller_openBody": "Count the cash in your drawer and enter it. If it doesn't match the books, the difference is recorded as a variance in your name, so count carefully.",
  "teller_balanceTitle": "Your till's money",
  "teller_balanceBody": "Balance is what the books say the drawer holds. Available is that less cash already promised to another till or the vault: you can't pay it out. Pending in is cash others are sending you.",
  "teller_waitingTitle": "Waiting for you",
  "teller_waitingBody": "Cash movements only you can complete. As vault custodian you approve cash leaving the vault and accept cash returned to it; as a teller you accept cash sent to your till. Nothing moves until it's accepted.",
  "teller_tillBalanceTitle": "Tills & Vaults",
  "teller_tillBalanceBody": "Every cash drawer of every branch. A vault is the branch safe (one per currency); tills are the counters. The balance is what the books say the drawer holds.",
  "teller_availableTitle": "Available",
  "teller_availableBody": "The balance less cash already promised to another till or the vault, waiting for them to accept. A teller cannot pay this cash out.",
  "teller_openByTitle": "Open by",
  "teller_openByBody": "The teller working this till now. Each till has one teller at a time.",
  "teller_movementsTitle": "Movements",
  "teller_movementsBody": "Every cash movement of this till since it was opened today. Money in is cash received; money out is cash paid or sent.",
  "teller_varianceTitle": "Variance",
  "teller_varianceBody": "The difference between the cash counted at close and what the books expected. A negative number means the till was short; it is booked as a teller cash variance expense.",
  takeTour: "Take a tour",
  stepOf: "Step {{step}} of {{total}}",
  next: "Next",
  nextOpens: "Next: open it",
  back: "Back",
  skip: "Skip tour",
