  tableTitle: "The records",
  tableBody: "One row per record. The status columns show whether it's Active, where it is in the approval flow (Draft, Pending, Approved) and its authorization status.",
  rowActionsTitle: "Row actions",
  rowActionsBody: "The buttons on each row. You only see the ones that fit that record's status and your permissions, so they change from row to row.",
  action_viewTitle: "View",
