  action_editTitle: "Edit",
  action_editBody: "Change the record. The change goes for approval; until a checker approves it, the approved version stays in use.",
  action_auditTitle: "Audit trail",
  action_auditBody: "Every version of the record: who changed what, when, and who approved it.",
  action_submitTitle: "Submit",
  action_submitBody: "Sends a draft for approval. A draft isn't used anywhere until it's submitted and approved.",
  action_authorizeTitle: "Authorize",
  action_authorizeBody: "For a checker: shows exactly what changed, then approves it so it takes effect. You can't authorize a change you made yourself.",
  action_rejectTitle: "Reject",
  action_rejectBody: "For a checker: sends the change back to the maker with a reason. The approved version stays as it was.",
  action_deactivateTitle: "Deactivate",
  action_deactivateBody: "Stops the record being used, without deleting it. Also needs a checker's approval.",
  action_reactivateTitle: "Reactivate",
  action_reactivateBody: "Brings an inactive record back into use, once a checker approves it.",
  action_deleteTitle: "Delete",
  action_deleteBody: "Removes the record. A draft is deleted straight away; anything else goes for approval first.",
  makerCheckerTitle: "How approval works (maker-checker)",
  makerCheckerBody: "Every change needs two people. The maker adds or changes a record and saves it as a draft or submits it. A different user, the checker, then authorizes it (it becomes Active) or rejects it (it goes back to the maker). Edits, deactivation, reactivation and deletion follow the same path, and the approved version stays in use until the change is approved.",
  addTitle: "Add a record",
  addBody: "Creates a new record. It starts as a draft or goes straight for approval, depending on how you save it.",
  addOpensTitle: "Add a record",
  addOpensBody: "Let's add one together. Press Next and the form opens; nothing is saved unless you save it yourself.",
  saveDraftTitle: "Save as draft",
  saveDraftBody: "Keeps your work without sending it for approval. Come back any time, finish it, then Submit from the row.",
  saveSubmitTitle: "Save and send for approval",
  saveSubmitBody: "Saves and sends it to a checker. It takes effect once they authorize it. That's the end of the tour: the form stays open with anything you've typed.",
  risk_institutionTitle: "Institution",
