  risk_customerTypeTitle: "Customer type",
  risk_customerTypeBody: "Which customers this setup scores: party type, ownership and, optionally, a sub type. Each customer type has one setup, and it's fixed once added.",
  risk_criteriaTitle: "Criteria",
  risk_criteriaBody: "The onboarding answers that make up the score, such as occupation or nationality. Open a criterion to score each of its options from 0 (no risk) to 100 (highest risk). Options left blank count as 0.",
  risk_addCriterionTitle: "Add a criterion",
  risk_addCriterionBody: "Pick a field here. Its options load automatically so you can score them.",
  risk_weightTotalTitle: "Weights add up to 100",
  risk_weightTotalBody: "Each criterion has a weight: how much it counts. They must total exactly 100; this turns green when they do. Spread evenly shares 100 between them.",
  risk_levelBarTitle: "Risk levels",
  risk_levelBarBody: "The levels split the 0–100 score into bands, such as Low, Medium and High. This bar shows how they cover the range.",
